const t={ui:{fig:"Fig. 1",title:"Pochette con zip · anatomia",svgLabel:"Un disegno isometrico della pochette con zip foderata e angoli tondi e di come si cuce, passo dopo passo.",prev:"Passo precedente",dot:(a,e)=>a?`Passo ${a}: ${e}`:e,start:"Passo passo →",next:"Avanti →",overview:"Panoramica",stepOf:(a,e)=>`Passo ${a} di ${e}`,machine:a=>`Macchina: ${a.toLowerCase()}`,inThisStep:"In questo passo",takeApart:"Scomponi",putTogether:"Ricomponi",replay:"↻ Ripeti",parts:"Parti",allSteps:"Istruzioni passo passo",endView:"SEZIONE",cutTitle:"Pochette con zip · misure di taglio",cutAlt:"Schema di taglio di una pochette con zip foderata: esterno e fodera di 23 × 31 cm ciascuno, teletta termoadesiva leggera di 21 × 29 cm, quattro pezzi rosa di 18 × 10 cm, un quadrato di teletta di 16 × 16 cm per gli angoli tondi e una cerniera di 20 cm.",cutCaption:"I pezzi da tagliare, con le loro misure, come nel passaggio 1."},stitches:{straight:"Punto dritto"},labels:{cm23:"23 cm",cm31:"31 cm",cm29:"29 cm",cm21:"21 cm",cm18:"18 cm",cm10:"10 cm",cm16:"16 cm",cm20:"20 cm",cm1:"1 cm",cm35:"3,5 cm",cm25:"2,5 cm",outerCotton:"esterno · cotone",liningCotton:"fodera · stessa misura",ifaceThin:"teletta leggera",pink4:"4 × rosa",ifaceCorners:"per gli angoli",zipper:"cerniera",radius8:"raggio 8 cm",paperTemplate:"sagoma di carta",cutInHalf:"taglia a metà",twoHalves:"due semicerchi",ironOn:"stira",rightSides:"dritto contro dritto",alongEdge:"cuci sul bordo",makeTwo:"fanne due",trimNotch:"rifila, fai i taglietti",turnOut:"rivolta sul dritto",wrongSideUp:"esterno, rovescio sopra",edges1:"1 cm dai bordi",middleBottom:"metà = fondo",rightSideUp:"dritto sopra",onBottomLine:"sulla linea del fondo",stitchRound:"cuci tutto intorno",straight05:"lato piatto: 0,5 cm",outerUp:"esterno, dritto sopra",zipperDown:"zip dritto sotto",liningDown:"fodera dritto sotto",seam05:"cucitura 0,5 cm",liningAway:"apri la fodera",foldBoth:"piega entrambi",otherSide:"l'altro lato",openZipper:"apri la zip",opening6:"apertura 6 cm",outerHalf:"esterno",liningHalf:"fodera",cutCorners:"taglia gli angoli",pinchSew:"apri, cuci di traverso",allFour:"tutti e quattro gli angoli",turnThrough:"rivolta dall'apertura",byHand:"chiudi a mano",pushLining:"infila la fodera",closeZip:"chiudi la zip"},steps:[{title:"La pochette finita",text:"Una pochette con zip foderata per trucchi, matite, tubetti e creme: cotone stampato con teletta leggera e un angolo tondo rosa a ogni estremità del fondo. Tocca la pochette per scomporla."},{title:"Taglia i pezzi",text:"Esterno e fodera: 23 × 31 cm ciascuno. Teletta termoadesiva leggera: 21 × 29 cm e un quadrato di 16 × 16 cm. Quattro pezzi rosa di 18 × 10 cm. Una cerniera di 20 cm.",details:["Dal cotone stampato taglia l'esterno, 23 × 31 cm. Taglia la fodera della stessa misura, 23 × 31 cm.","Dalla teletta termoadesiva leggera taglia un pezzo di 21 × 29 cm per l'esterno e un quadrato di 16 × 16 cm per gli angoli tondi.","Dal cotone rosa taglia quattro pezzi di 18 × 10 cm: due per ogni angolo.","Ti serve anche una cerniera di 20 cm.","Tutti i margini di cucitura di questa pochette sono di 0,5 cm."]},{title:"La sagoma degli angoli",text:"Disegna su carta un cerchio di 8 cm di raggio e ritaglialo. Ricalcalo sul quadrato di teletta da 16 cm, ritaglia il cerchio e taglialo a metà.",details:["Prepara una sagoma di carta: un cerchio di 8 cm di raggio.","Ricalca il cerchio sul quadrato di teletta di 16 × 16 cm e ritaglialo.","Taglia il cerchio a metà: due semicerchi, uno per ogni angolo tondo."]},{title:"Cuci le mezzelune",text:"Stira un semicerchio sul rovescio di un pezzo rosa, al centro, con il lato piatto a 1 cm dal bordo lungo. Mettici sotto un secondo pezzo rosa, dritto contro dritto, e cuci lungo il bordo curvo della teletta.",details:["Appoggia un semicerchio di teletta, lato colla in giù, sul rovescio di un pezzo rosa: al centro, con il lato piatto a 1 cm da un bordo lungo. Stiralo.","Mettilo su un secondo pezzo rosa, dritto contro dritto.","Cuci lungo la curva, proprio sul bordo della teletta.","Fai la seconda nello stesso modo."]},{title:"Rifila e rivolta",text:"Rifila la stoffa intorno alla curva, fai dei taglietti nel margine e rivolta ogni mezzaluna sul dritto. Stira.",details:["Taglia la stoffa in eccesso intorno alla curva, lasciando un margine stretto.","Fai dei taglietti nel margine lungo la curva, così resta piatto.","Rivolta entrambe le mezzelune sul dritto dal lato piatto e stirale. Il lato piatto resta aperto."]},{title:"Stira la teletta",text:"Stira la teletta di 21 × 29 cm sul rovescio dell'esterno, a 1 cm da ogni bordo. Piega l'esterno a metà e segna il centro con dei taglietti: è il fondo.",details:["Appoggia l'esterno con il rovescio in su.","Mettici sopra la teletta, lato colla in giù, a 1 cm da ogni bordo, e stirala. La fodera non ha teletta.","Piega l'esterno a metà nel senso della larghezza e fai un piccolo taglietto alle due estremità della piega. La piega è il fondo della pochette: lì non c'è cucitura."]},{title:"Applica le mezzelune",text:"Sul dritto dell'esterno metti una mezzaluna su ogni bordo laterale, con il centro sulla linea del fondo e il bordo rettilineo a filo del lato, e cucila tutto intorno.",details:["Gira l'esterno con il dritto in su.","Metti una mezzaluna su ogni bordo laterale: il bordo rettilineo aperto a filo del bordo dell'esterno, il centro sui taglietti, cioè sulla linea del fondo.","Cuci ognuna tutto intorno: lungo la curva proprio sul bordo, lungo il lato piatto a 0,5 cm dal bordo. Il lato piatto finirà nella cucitura laterale."]},{title:"Cerniera: primo lato",text:"L'esterno con il dritto in su, la cerniera con il dritto in giù al centro di un lato corto, sopra la fodera con il dritto in giù. Cuci a 0,5 cm dal bordo.",details:["Appoggia l'esterno con il dritto in su.","Metti la cerniera con il dritto in giù lungo un lato di 23 cm, al centro: le estremità non arrivano ai bordi laterali e restano fuori dalle cuciture laterali.","Sopra metti la fodera con il dritto in giù, bordo contro bordo con l'esterno.","Cuci attraverso tutti gli strati, a 0,5 cm dal bordo. Nessuna impuntura lungo la cerniera."]},{title:"Cerniera: secondo lato",text:"Apri la fodera lontano dalla cerniera. Piega a metà l'esterno e la fodera, così i loro altri lati corti arrivano all'altro lato della cerniera, e cucili nello stesso modo.",details:["Apri la fodera lontano dalla cerniera.","Piega l'esterno a metà sulla linea del fondo, dritto contro dritto, e la fodera nello stesso modo.","I loro altri lati corti arrivano ora all'altro lato della cerniera: esterno, cerniera con il dritto in giù, fodera, come la prima volta.","Cuci a 0,5 cm dal bordo. L'esterno e la fodera ora formano un anello."]},{title:"Cuciture laterali",text:"Apri la cerniera. Stendi la pochette, esterno su esterno e fodera su fodera, dritto contro dritto, e cuci i due lati, lasciando un'apertura di 6 cm al centro di un lato della fodera.",details:["Prima apri la cerniera: da lì poi si rivolta la pochette.","Stendila: l'esterno dritto contro dritto da una parte della cerniera, la fodera dall'altra.","Cuci le due cuciture laterali a 0,5 cm dal bordo, prendendo anche le mezzelune.","Su un lato della fodera lascia aperti 6 cm, al centro della cucitura."]},{title:"Gli angoli del fondo",text:"Da ogni angolo in basso, due sull'esterno e due sulla fodera, taglia un rettangolo di 3,5 × 2,5 cm: 3,5 cm lungo il fondo, 2,5 cm lungo la cucitura laterale. Apri ogni angolo e cuci di traverso.",details:["Disegna in ognuno dei quattro angoli in basso un rettangolo di 3,5 × 2,5 cm: 3,5 cm lungo il fondo, 2,5 cm lungo la cucitura laterale.","Ritagliali.","Apri ogni angolo e appiattiscilo in modo che la cucitura laterale cada sulla piega del fondo.","Cuci di traverso a 0,5 cm dal bordo. Fai tutti e quattro gli angoli."]},{title:"Rivolta",text:"Rivolta la pochette sul dritto dall'apertura nella fodera e dalla cerniera aperta. Chiudi l'apertura a mano, infila la fodera dentro e chiudi la cerniera.",details:["Tira fuori l'esterno dall'apertura nella fodera e dalla cerniera aperta.","Ripiega all'interno i bordi dell'apertura e chiudila a mano.","Infila la fodera nella pochette, fino negli angoli, e chiudi la cerniera. Le mezzelune sono diventate angoli tondi rosa."]}],legend:[{title:"Esterno",text:"cotone stampato · 23 × 31 cm, piegato a metà: la piega è il fondo"},{title:"Teletta",text:"leggera, termoadesiva · 21 × 29 cm, sull'esterno, a 1 cm dai bordi"},{title:"Angoli tondi ×2",text:"quattro pezzi rosa di 18 × 10 cm · semicerchi di teletta di 8 cm di raggio, da un quadrato di 16 × 16 cm"},{title:"Cerniera",text:"20 cm · al centro dei lati corti, senza impuntura"},{title:"Fodera",text:"cotone · 23 × 31 cm, senza teletta"},{title:"Cuciture",text:"tutte a 0,5 cm · un'apertura di 6 cm nella fodera, chiusa a mano · angoli: tagliati 3,5 × 2,5 cm"}]};export{t as default};
